m=json.loads(mp.read_text()); rows=[]; bad=[]
for e in m['entries']:
 p=root/e['path']; kind=e['kind']; status='ok'; observed=None
 try:
  st=p.lstat()
  if kind=='directory':
   if not stat.S_ISDIR(st.st_mode): status='type-mismatch'
  elif kind=='file':
   if stat.S_ISLNK(st.st_mode):
    raw=os.readlink(p).encode(); observed=hashlib.sha256(raw).hexdigest()
    if observed!=e['sha256']: status='link-bytes-hash-mismatch'
   elif stat.S_ISREG(st.st_mode):
    h=hashlib.sha256()
    with p.open('rb') as f:
     for b in iter(lambda:f.read(1<<20),b''): h.update(b)
    observed=h.hexdigest()
    if observed!=e['sha256']: status='file-hash-mismatch'
    if st.st_size!=e.get('size'): status='size-mismatch'
   else: status='type-mismatch'
  else: status='unknown-kind'
 except FileNotFoundError: status='missing'
 row={'path':e['path'],'expected_kind':kind,'status':status}
 if observed is not None: row['observed_sha256']=observed
 if status!='ok': bad.append(row)
