inputs=[]
for e in receipt.get('seed_identities',{}).get('inputs',[]):
 p=root/e['path']
 try:
  resolved=p.resolve(strict=True)
  safe=resolved.is_relative_to(root.resolve())
  h=hashlib.sha256(resolved.read_bytes()).hexdigest() if safe else None
  status='ok' if safe and h==e['sha256'] else ('external-target' if not safe else 'content-hash-mismatch')
 except FileNotFoundError: status='unresolved'
 inputs.append({'path':e['path'],'status':status,'sha256':h if 'h' in locals() else None})
 if status!='ok': bad.append(inputs[-1])
result={'manifest':str(mp),'manifest_sha256':hashlib.sha256(mp.read_bytes()).hexdigest(),'capture_status':m.get('capture_status'),'entries_checked':len(rows),'entry_mismatches':bad,'worker_seed_inputs_checked':len(inputs),'input_mismatches':[x for x in inputs if x['status']!='ok'],'result':'match' if not bad else 'mismatch'}
