steps=[('stamp',[*base,'response','stamp',str(out/'2026-10-16-response.json'),'--harness','Codex API session','--model','GPT-6','--scope','Complete captured worker-stop delivery; manifest verified; inspected full capture and ran frozen probes. Scientific replay not checked because no worker-supplied environment specification exists and the documented interpreter is outside the delivery.','--kind','study','--dependency','assess-alignment-with-stamped-principles@0.2.0','--dependency','stamped-conventions@0.2.0','--capture',os.environ['STAMPED_DELIVERY_MANIFEST']),('validate',[*base,'validate',str(out/'2026-10-16-response.json')]),('encode',[*base,'response','encode',str(out/'2026-10-16-response.json')])]
for name,argv in steps:
 r=subprocess.run(argv,text=True,capture_output=True)
 (out/f'{name}-command.json').write_text(json.dumps({'argv':argv,'returncode':r.returncode},indent=2)+'\n')
 (out/f'{name}-stdout.txt').write_text(r.stdout);(out/f'{name}-stderr.txt').write_text(r.stderr)
 if r.returncode: raise SystemExit(f'{name} failed: {r.stderr}')
